import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetPlatform } from "../types.ts";
import type { ParticipantProfileFields } from "./skipMatrix.ts";

export type ParticipantProfileRow = ParticipantProfileFields & {
  id: string;
  organization_id: string;
  platform: LeadMagnetPlatform;
  participant_scoped_id: string;
  canonical_lead_id: string | null;
  canonical_submission_id: string | null;
  last_delivery_channel: "instagram" | "whatsapp" | "email" | null;
};

export async function getParticipantProfile(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    platform: LeadMagnetPlatform;
    participantScopedId: string;
  },
): Promise<ParticipantProfileRow | null> {
  const { data } = await admin
    .from("lead_magnet_participant_profiles")
    .select("*")
    .eq("organization_id", args.organizationId)
    .eq("platform", args.platform)
    .eq("participant_scoped_id", args.participantScopedId)
    .maybeSingle();
  return (data as ParticipantProfileRow | null) ?? null;
}

export async function upsertParticipantContactField(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    platform: LeadMagnetPlatform;
    participantScopedId: string;
    phoneNumber?: string | null;
    email?: string | null;
    canonicalLeadId?: string | null;
    canonicalSubmissionId?: string | null;
    lastDeliveryChannel?: "instagram" | "whatsapp" | "email" | null;
  },
): Promise<ParticipantProfileRow | null> {
  const now = new Date().toISOString();
  const existing = await getParticipantProfile(admin, {
    organizationId: args.organizationId,
    platform: args.platform,
    participantScopedId: args.participantScopedId,
  });

  const patch: Record<string, unknown> = { updated_at: now };
  if (args.phoneNumber !== undefined) patch.phone_number = args.phoneNumber;
  if (args.email !== undefined) patch.email = args.email;
  if (args.canonicalLeadId !== undefined) patch.canonical_lead_id = args.canonicalLeadId;
  if (args.canonicalSubmissionId !== undefined) {
    patch.canonical_submission_id = args.canonicalSubmissionId;
  }
  if (args.lastDeliveryChannel !== undefined) patch.last_delivery_channel = args.lastDeliveryChannel;

  if (existing?.id) {
    const { data } = await admin
      .from("lead_magnet_participant_profiles")
      .update(patch)
      .eq("id", existing.id)
      .select("*")
      .maybeSingle();
    return (data as ParticipantProfileRow | null) ?? null;
  }

  const { data } = await admin
    .from("lead_magnet_participant_profiles")
    .insert({
      organization_id: args.organizationId,
      platform: args.platform,
      participant_scoped_id: args.participantScopedId,
      phone_number: args.phoneNumber ?? null,
      email: args.email ?? null,
      canonical_lead_id: args.canonicalLeadId ?? null,
      canonical_submission_id: args.canonicalSubmissionId ?? null,
      last_delivery_channel: args.lastDeliveryChannel ?? null,
      created_at: now,
      updated_at: now,
    })
    .select("*")
    .maybeSingle();
  return (data as ParticipantProfileRow | null) ?? null;
}

export async function syncSubmissionContactFields(
  admin: SupabaseClient,
  submissionId: string | null | undefined,
  fields: {
    phoneNumber?: string | null;
    email?: string | null;
    leadMagnetCampaignName?: string | null;
    leadMagnetTargetMarket?: string | null;
  },
): Promise<void> {
  if (!submissionId) return;

  const { data: existing } = await admin
    .from("lead_submissions")
    .select("lead_magnet_campaign_name, lead_magnet_target_market")
    .eq("id", submissionId)
    .maybeSingle();

  const patch: Record<string, unknown> = { updated_at: new Date().toISOString() };
  if (fields.phoneNumber !== undefined) patch.phone_number = fields.phoneNumber;
  if (fields.email !== undefined) patch.email = fields.email;

  const snapshotName = fields.leadMagnetCampaignName?.trim() || null;
  const snapshotMarket = fields.leadMagnetTargetMarket?.trim() || null;
  const existingName = existing?.lead_magnet_campaign_name != null
    ? String(existing.lead_magnet_campaign_name).trim()
    : "";
  const existingMarket = existing?.lead_magnet_target_market != null
    ? String(existing.lead_magnet_target_market).trim()
    : "";

  if (snapshotName && !existingName) patch.lead_magnet_campaign_name = snapshotName;
  if (snapshotMarket && !existingMarket) patch.lead_magnet_target_market = snapshotMarket;

  await admin.from("lead_submissions").update(patch).eq("id", submissionId);
}

import type { LeadMagnetCampaignRow } from "../types.ts";

export type ParticipantProfileFields = {
  phone_number: string | null;
  email: string | null;
};

export type MissingContactField = "any" | "phone" | "email";

export type ContactGateFlowBranch =
  | { branch: "legacy_material_or_delivery" }
  | { branch: "needs_follow_gate" }
  | { branch: "needs_contact"; ask: MissingContactField }
  | { branch: "deliver_instagram" };

export function isContactGateEnabled(
  campaign: Pick<LeadMagnetCampaignRow, "contact_gate_enabled">,
): boolean {
  return campaign.contact_gate_enabled === true;
}

export function getMissingContactFields(profile: ParticipantProfileFields): MissingContactField | null {
  const hasPhone = Boolean(profile.phone_number?.trim());
  const hasEmail = Boolean(profile.email?.trim());
  if (hasPhone && hasEmail) return null;
  if (hasPhone && !hasEmail) return "email";
  if (!hasPhone && hasEmail) return "phone";
  return "any";
}

export function resolveFlowBranch(args: {
  campaign: Pick<LeadMagnetCampaignRow, "contact_gate_enabled">;
  profile: ParticipantProfileFields;
  isFollower: boolean;
}): ContactGateFlowBranch {
  if (!isContactGateEnabled(args.campaign)) {
    return { branch: "legacy_material_or_delivery" };
  }
  if (!args.isFollower) {
    return { branch: "needs_follow_gate" };
  }
  const missing = getMissingContactFields(args.profile);
  if (!missing) {
    return { branch: "deliver_instagram" };
  }
  return { branch: "needs_contact", ask: missing };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getOrCreateSystemActor, resolveLeadStatusId } from "../omnichannelPublicApi/leadStatusMap.ts";
import { resolveLeadMagnetAccountLabel } from "./resolveLeadMagnetAccountLabel.ts";
import {
  getParticipantProfile,
  upsertParticipantContactField,
} from "./contactGate/participantProfile.ts";
import type { LeadMagnetCampaignRow, LeadMagnetPlatform } from "./types.ts";

export async function createLeadMagnetLead(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    campaign: LeadMagnetCampaignRow;
    enrollmentId: string;
    participantUsername: string | null;
    participantScopedId: string;
    platform: LeadMagnetPlatform;
    mediaId: string;
  },
): Promise<{ leadId: string; leadSubmissionId: string } | null> {
  try {
    const { data: existingEnrollment } = await admin
      .from("lead_magnet_enrollments")
      .select("id, lead_id, lead_submission_id")
      .eq("id", args.enrollmentId)
      .maybeSingle();

    if (existingEnrollment?.lead_id) {
      return {
        leadId: String(existingEnrollment.lead_id),
        leadSubmissionId: String(existingEnrollment.lead_submission_id ?? ""),
      };
    }

    const canonicalProfile = await getParticipantProfile(admin, {
      organizationId: args.organizationId,
      platform: args.platform,
      participantScopedId: args.participantScopedId,
    });

    if (canonicalProfile?.canonical_lead_id && canonicalProfile.canonical_submission_id) {
      await admin
        .from("lead_magnet_enrollments")
        .update({
          lead_id: canonicalProfile.canonical_lead_id,
          lead_submission_id: canonicalProfile.canonical_submission_id,
          updated_at: new Date().toISOString(),
        })
        .eq("id", args.enrollmentId);
      return {
        leadId: canonicalProfile.canonical_lead_id,
        leadSubmissionId: canonicalProfile.canonical_submission_id,
      };
    }

    const actor = await getOrCreateSystemActor(admin, args.organizationId);
    const statusId = await resolveLeadStatusId(admin, args.organizationId, "new");
    const accountLabel = await resolveLeadMagnetAccountLabel(admin, {
      organizationId: args.organizationId,
      campaignId: args.campaign.id,
      platform: args.platform,
      legacyAccountId: args.campaign.account_id,
    });

    const displayName = (args.participantUsername ?? "").trim().replace(/^@/, "") ||
      `${args.platform === "instagram" ? "IG" : "FB"} ${args.participantScopedId.slice(0, 8)}`;
    const now = new Date().toISOString();
    const channelLabel = args.platform === "instagram" ? "Instagram Comment" : "Facebook Comment";

    const leadId = crypto.randomUUID();
    const ticketId = "LEAD-" + leadId.replace(/-/g, "").slice(0, 8).toUpperCase();

    const { error: leadErr } = await admin.from("leads").insert({
      id: leadId,
      ticket_id: ticketId,
      client: displayName,
      title: `Lead Magnet — ${args.campaign.name}`.slice(0, 120),
      category: "Lead Magnet",
      source: "Lead Magnet",
      services: channelLabel,
      organization_id: args.organizationId,
      created_by: actor.userId,
      created_by_name: accountLabel,
      assignee: "Unassigned",
      status_id: statusId,
      web_id: null,
      created_at: now,
      updated_at: now,
    });

    if (leadErr) {
      console.error("[lead-magnet] leads insert failed:", leadErr.message);
      return null;
    }

    const submissionId = crypto.randomUUID();
    const submissionPayload: Record<string, unknown> = {
      id: submissionId,
      organization_id: args.organizationId,
      lead_id: leadId,
      form_id: null,
      name: displayName,
      status: "draft",
      is_active: true,
      lead_magnet_enrollment_id: args.enrollmentId,
      lead_magnet_campaign_id: args.campaign.id,
      notes: `Lead magnet keyword "${args.campaign.keyword}" on media ${args.mediaId}`,
      updated_at: now,
    };

    const { error: subErr } = await admin.from("lead_submissions").insert(submissionPayload);

    if (subErr) {
      console.error("[lead-magnet] lead_submissions insert failed:", subErr.message);
      return { leadId, leadSubmissionId: submissionId };
    }

    await admin
      .from("lead_magnet_enrollments")
      .update({ lead_id: leadId, lead_submission_id: submissionId, updated_at: now })
      .eq("id", args.enrollmentId);

    await upsertParticipantContactField(admin, {
      organizationId: args.organizationId,
      platform: args.platform,
      participantScopedId: args.participantScopedId,
      canonicalLeadId: leadId,
      canonicalSubmissionId: submissionId,
      phoneNumber: canonicalProfile?.phone_number ?? null,
      email: canonicalProfile?.email ?? null,
    });

    return { leadId, leadSubmissionId: submissionId };
  } catch (err) {
    console.error("[lead-magnet] createLeadMagnetLead error:", err);
    return null;
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildLeadMagnetDownloadUrl } from "../leadMagnetActionUrl.ts";
import { interpolateLeadMagnetText } from "../types.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";
import { buildLeadMagnetAssetPublicUrl } from "../deliveryAsset.ts";

export type DeliveryContext = {
  username: string;
  deliveryUrl: string;
  campaignName: string;
};

export async function buildDeliveryContext(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
  },
): Promise<DeliveryContext> {
  const username = (args.enrollment.participant_username ?? "").trim().replace(/^@/, "") || "Kak";
  let deliveryUrl = String(args.campaign.delivery_url ?? "").trim();

  const storagePath = (args.campaign as { delivery_storage_path?: string | null }).delivery_storage_path;
  if (storagePath?.trim()) {
    const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").trim();
    if (supabaseUrl) {
      deliveryUrl = buildLeadMagnetAssetPublicUrl(supabaseUrl, storagePath.trim());
    }
  }

  if (!deliveryUrl) {
    deliveryUrl = await buildLeadMagnetDownloadUrl(args.enrollment.id);
  }

  return {
    username,
    deliveryUrl,
    campaignName: args.campaign.name,
  };
}

export function interpolateDeliveryTemplate(
  template: string,
  ctx: DeliveryContext,
): string {
  return template
    .replace(/\{\{username\}\}/gi, ctx.username)
    .replace(/\{\{delivery_url\}\}/gi, ctx.deliveryUrl)
    .replace(/\{\{campaign_name\}\}/gi, ctx.campaignName);
}

export function interpolateCampaignText(
  template: string,
  username: string | null,
): string {
  return interpolateLeadMagnetText(template, username);
}

export type WhatsAppTemplateParams = {
  body?: string[];
  header?: string[];
  button?: string[];
};

export function buildWhatsAppTemplateComponents(
  params: WhatsAppTemplateParams | null | undefined,
  ctx: DeliveryContext,
): Array<Record<string, unknown>> {
  const components: Array<Record<string, unknown>> = [];
  const mapVars = (vars: string[] | undefined): string[] =>
    (vars ?? []).map((v) => interpolateDeliveryTemplate(v, ctx));

  const bodyVars = mapVars(params?.body);
  if (bodyVars.length > 0) {
    components.push({
      type: "body",
      parameters: bodyVars.map((text) => ({ type: "text", text })),
    });
  }

  const headerVars = mapVars(params?.header);
  if (headerVars.length > 0) {
    components.push({
      type: "header",
      parameters: headerVars.map((text) => ({ type: "text", text })),
    });
  }

  const buttonVars = mapVars(params?.button);
  if (buttonVars.length > 0) {
    components.push({
      type: "button",
      sub_type: "url",
      index: "0",
      parameters: buttonVars.map((text) => ({ type: "text", text })),
    });
  }

  return components;
}
